/* One navigation surface; the existing Linux-to-K8s classroom remains intact.
 * All tracks use read -> verify -> confirm -> quiz -> explicit next. */
const baseRender=render,baseNav=navHTML;
let hubSubject='ops',hubTrack='opswork',hubLesson=0,hubPhase='learn',hubAttempt,hubEngine,hubOutput='',hubLevel='全部',hubBrowse=null,jpLevel='N5',jpType='vocab',jpQuery='',jpPage=0,jpRows=[],jpStatus='';
let hubState={attempts:{},completed:{}};try{const s=JSON.parse(localStorage.getItem('learning-hub-v1'));if(s?.attempts&&s?.completed)hubState=s;}catch(e){}
for(const key of Object.keys(hubCurriculum)){const lessons=hubCurriculum[key];hubState.completed[key]=(hubState.completed[key]||[]).filter(id=>{const c=lessons.find(x=>x.id===id),a=hubState.attempts[key+':'+id];return c&&a?.read&&a.step===c.tasks.length&&a.passed&&a.answer===c.quiz.answer;});}
function hubSave(){try{localStorage.setItem('learning-hub-v1',JSON.stringify(hubState));}catch(e){toast('本设备无法保存新课程进度；刷新后可能丢失。');}}
function hubNextIndex(track){const list=hubCurriculum[track];const i=list.findIndex(c=>!hubState.completed[track].includes(c.id));return i<0?list.length-1:i;}
function hubUnlocked(track,i){return i>=0&&i<hubCurriculum[track].length&&i<=hubNextIndex(track);}
function activeHubLesson(){return hubCurriculum[hubTrack][hubLesson];}
function hubPassed(){const c=activeHubLesson();return hubAttempt.read&&hubAttempt.step===c.tasks.length&&hubAttempt.passed&&hubAttempt.answer===c.quiz.answer;}
function setHubCompletion(){const c=activeHubLesson(),list=hubState.completed[hubTrack];hubState.completed[hubTrack]=list.filter(id=>id!==c.id);if(hubPassed())hubState.completed[hubTrack].push(c.id);hubSave();}
function openHubLesson(track,i){if(!hubUnlocked(track,i))return toast('先完成上一关的操作与小测。');hubTrack=track;hubSubject=track==='opswork'?'ops':track;hubLesson=i;hubBrowse=null;const key=track+':'+activeHubLesson().id;hubAttempt=hubState.attempts[key]||{read:false,step:0,verified:false,draft:'',answer:null,passed:false,feedback:'',phase:'learn'};hubState.attempts[key]=hubAttempt;hubPhase=hubAttempt.phase||'learn';if(hubPhase==='practice'&&!hubAttempt.read||hubPhase==='quiz'&&hubAttempt.step!==activeHubLesson().tasks.length)hubPhase='learn';hubEngine=new JobEngine();if(hubAttempt.files)Object.assign(hubEngine.fs,hubAttempt.files);hubOutput=hubAttempt.output||'';view='hub-course';hubSave();render();window.scrollTo({top:0,behavior:'instant'});}
function hubNav(){return `<header class="hub-header"><button class="brand" data-hub="home"><span class="brand-icon">知</span><span>知行学习室<small>从理解，到亲手做到</small></span></button><nav aria-label="学习导航"><button data-hub="home" ${view==='hub'?'aria-current="page"':''}>学习首页</button><button data-hub="books" ${view==='books'||view==='reader'?'aria-current="page"':''}>阅读书房</button><button data-hub="jp-library">日语知识库</button><button data-action="view" data-view="demos">可视化</button></nav><span class="saved">手机 · 电脑 / 本设备进度</span></header><div class="subject-bar" aria-label="课程种类">${Object.entries(hubSubjects).map(([id,s])=>`<button data-hub="subject" data-id="${id}" class="${hubSubject===id?'active':''}"><b>${s.mark}</b>${s.name}</button>`).join('')}</div>`;}
navHTML=function(){return hubNav()+`<div class="ops-nav">${[['classroom','基础闯关'],['roadmap','基础路线'],['manual','命令手册'],['labs','综合演练'],['demos','原理演示']].map(([id,t])=>`<button data-action="view" data-view="${id}" class="${view===id?'active':''}">${t}</button>`).join('')}<button data-hub="subject" data-id="ops">工作实战</button></div>`;};
render=function(){if(['hub','hub-course','subject','books','reader','jp-library','anime'].includes(view)){const html=view==='hub'?hubHome():view==='subject'?subjectHTML():view==='hub-course'?hubCourseHTML():view==='books'?booksHTML():view==='reader'?readerHTML():view==='anime'?animeHTML():jpLibraryHTML();$('app').innerHTML=hubNav()+html;if(view==='hub-course'&&hubPhase==='practice'){$('hub-draft').value=hubAttempt.draft||'';$('hub-form')?.addEventListener('submit',e=>{e.preventDefault();verifyHubTask();});}if(view==='jp-library')paintJPResults();}else{hubSubject='ops';baseRender();}};
function hubHome(){return `<main class="hub-main"><section class="hub-hero"><div><div class="eyebrow">LEARN BY DOING / 每天前进一步</div><h1>把知识，<br>变成能用的本领。</h1><p>先把工作中的问题解决：命令写得更清楚，日志找得更快，数据库查得更准。再向网络、语言与阅读扩展。</p><div class="hero-actions"><button class="primary" data-hub="lesson" data-track="opswork" data-index="${hubNextIndex('opswork')}">继续运维工作实战</button><button class="secondary" data-action="continue">从 Linux 基础开始</button></div><div class="hero-stats"><span><b>${courses.length+hubCurriculum.opswork.length}</b>运维核心课</span><span><b>5</b>学习领域</span><span><b>逐步验证</b>做对才前进</span></div></div><img src="assets/learning-journey.webp" alt="从终端、网络到数据库与服务器的阶梯学习插画"></section><section class="ops-feature"><div><div class="eyebrow">YOUR WORK FIRST / 运维是主线</div><h2>页面报错了，下一步从哪里查？</h2><p>页面请求 Nginx 进程 / 容器 / Pod 应用日志 DM8 数据源与业务表。用一个虚构订单系统练完整链路。</p></div><button class="primary" data-hub="subject" data-id="ops">进入工作实战</button></section><div class="subject-grid">${Object.entries(hubSubjects).map(([id,s])=>`<button class="subject-card ${s.tone}" data-hub="subject" data-id="${id}"><span class="subject-mark">${s.mark}</span><small>${s.tag}</small><h2>${s.name}</h2><p>${s.description}</p><span class="card-link">${id==='ops'?'基础 51 课 + 工作实战 '+hubCurriculum.opswork.length+' 课':hubCurriculum[id].length+' 节引导课程'}</span></button>`).join('')}</div><section class="section"><h2>怎样在这里学习</h2><div class="method-grid"><p><b>1 · 读懂</b><br>先看场景、标准用法和关联知识。</p><p><b>2 · 亲手做</b><br>输入命令或完成任务，观察并验证结果。</p><p><b>3 · 通关</b><br>确认每一步，再回答小测，手动进入下一关。</p></div><p class="small-note">所有命令与数据库结果都是本地教学模拟，支持范围会明确说明。不连接工作服务器。进度暂不跨设备同步。</p></section></main>`;}
function subjectHTML(){const s=hubSubjects[hubSubject],track=hubSubject==='ops'?'opswork':hubSubject,list=hubCurriculum[track],sections=[...new Set(list.map(c=>c.section))];return `<main class="hub-main"><div class="page-head"><div><div class="eyebrow">${s.tag} / LEARNING PATH</div><h1>${s.name}</h1><p>${s.description}</p></div><span class="chip">${hubState.completed[track].length}/${list.length} 节通过</span></div>${hubSubject==='ops'?`<section class="ops-feature"><div><h2>贴近你的业务：部署、日志与 DM8</h2><p>先学管道，再沿页面请求追查服务，最后从接口定位 DM8 表和字段；部署检查、验证、维护与回退贯穿其中。</p><p class="small-note">已有基础路线：Linux Shell SQL / MySQL Docker Kubernetes。下方工作实战是独立闯关路线。</p></div><button class="secondary" data-action="continue">进入基础闯关</button></section>`:hubSubject==='japanese'?`<div class="resource-strip"><button class="secondary" data-hub="jp-library">7811 词 · 2383 汉字 · 526 文法</button><button class="secondary" data-hub="anime">官方动漫片段辅助学习</button><a href="https://www.jpfbj.cn/irodori/" target="_blank" rel="noopener noreferrer">官方《彩》真人音频</a></div><p class="small-note">先学五十音，再按 N5 N1 推进。口语与写作是补充训练；JLPT 考查语言知识、阅读和听力。分级核心课为学习骨架，搭配完整资源库与官方练习使用。</p>`:hubSubject==='agent'?animateResources():hubSubject==='writing'?'<div class="resource-strip"><button class="primary" data-hub="books">进入 EPUB 书房</button></div>':''}<div class="filter-tabs">${['全部',...sections].map(t=>`<button data-hub="section" data-value="${esc(t)}" class="${hubLevel===t?'active':''}">${esc(t)}</button>`).join('')}</div><div class="path-list">${list.map((c,i)=>hubLevel==='全部'||c.section===hubLevel?`<article class="path-card ${hubUnlocked(track,i)?'':'locked'}"><span class="path-number">${String(i+1).padStart(2,'0')}</span><div><small>${c.section}</small><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><details><summary>预览讲解</summary>${c.body.map(p=>`<p>${esc(p)}</p>`).join('')}${c.examples.map(e=>`<pre>${esc(e.text)}</pre><p>${esc(e.meaning)}</p>`).join('')}</details></div><button class="${hubUnlocked(track,i)?'primary':'secondary'}" data-hub="lesson" data-track="${track}" data-index="${i}" ${hubUnlocked(track,i)?'':'disabled'}>${hubState.completed[track].includes(c.id)?'复习已通关':hubUnlocked(track,i)?'开始这一关':'待解锁'}</button></article>`:'').join('')}</div><p class="small-note">可随时预览知识；操作与通关按顺序解锁。课程不宣称涵盖每个产品的全部版本与命令。</p></main>`;}
function simpleDiagram(kind){const maps={pipeline:['日志文本','grep 筛选','awk 提取','sort / uniq','统计与证据'],trace:['页面请求','Nginx 路由','服务日志','数据源 / SQL','DM8 对象'],database:['接口字段','SQL / Mapper','账号 / schema','表与列','只读样本'],deploy:['环境检查','配置校验','发布','业务验证','观测 / 回退'],network:['终端 / 网卡','交换机 / AP','网关 / 路由','DNS 解析','目标服务'],subnet:['IP 与前缀','同网段判断','下一跳','链路转发','服务请求'],dhcp:['客户端发现','服务器提供','客户端请求','服务器确认','配置地址'],switch:['收到帧','学习源 MAC','查目的 MAC','定向 / 泛洪','老化更新']};if(!maps[kind])return '';return `<div class="concept-flow" aria-label="${kind}流程">${maps[kind].map((n,i)=>`<span><small>${i+1}</small>${n}</span>`).join('')}</div>`;}
function hubCourseHTML(){const c=activeHubLesson(),a=hubAttempt,t=c.tasks[a.step],preview=hubBrowse!==null;return `<main class="hub-main"><div class="lesson-top"><button class="text-button" data-hub="subject" data-id="${hubSubject}">${hubSubjects[hubSubject].name}路线</button><span class="chip">关卡 ${hubLesson+1}/${hubCurriculum[hubTrack].length} · ${c.section}</span><button class="text-button" data-hub="reset-lesson">重练本关</button></div><h1>${esc(c.title)}</h1><div class="learning-tabs" role="tablist">${[['learn','1 · 理解'],['practice','2 · 操作'],['quiz','3 · 通关']].map(([id,label])=>`<button role="tab" aria-selected="${hubPhase===id}" data-hub="phase" data-id="${id}" ${id==='practice'&&!a.read||id==='quiz'&&a.step!==c.tasks.length?'disabled':''}>${label}</button>`).join('')}</div>${hubPhase==='learn'?`<div class="hub-lesson-grid"><article class="section lesson-text"><div class="eyebrow">从场景理解，再看标准用法</div>${c.body.map(p=>`<p>${esc(p)}</p>`).join('')}${simpleDiagram(c.diagram)}<h2>标准用法与例子</h2>${c.examples.map(e=>`<div class="worked-example"><pre>${esc(e.text)}</pre><p>${esc(e.meaning)}</p>${hubSubject==='japanese'?`<button class="secondary" data-hub="speak" data-text="${esc(e.text)}">听设备合成发音</button>`:''}</div>`).join('')}<h2>关联知识</h2><p>${esc(c.related)}</p><a href="${c.source[1]}" target="_blank" rel="noopener noreferrer">${esc(c.source[0])}</a><div class="course-start"><button class="primary" data-hub="read">我读懂了，开始练习</button></div></article><aside class="lesson-companion"><img src="assets/learning-journey.webp" alt="学习阶梯插画"><h2>一次只完成一步</h2><p>读懂 逐步验证 确认结果 小测通关。不会因为答错而自动跳转。</p><p>${a.step}/${c.tasks.length} 项操作已确认</p></aside></div>`:hubPhase==='practice'?`<section class="section"><div class="eyebrow">教学模拟 / 操作 ${Math.min(a.step+1,c.tasks.length)} of ${c.tasks.length}</div>${t?`<h2>${esc(t.prompt)}</h2><p>${esc(t.explanation)}</p>${t.type==='command'?`<pre>${esc(t.command)}</pre><button class="secondary" data-hub="fill-task">填入标准命令</button>`:t.hint?`<p class="small-note">${esc(t.hint)}</p>`:''}<form id="hub-form">${t.type==='choice'?`<fieldset><legend>选择一个选项，再验证</legend>${t.options.map((o,i)=>`<label class="hub-option ${a.draft===String(i)?'is-selected':''}"><input type="radio" name="hub-task" value="${i}" ${a.draft===String(i)?'checked':''} ${a.verified?'disabled':''}><span>${esc(o)}</span></label>`).join('')}</fieldset><input id="hub-draft" type="hidden">`:`<label for="hub-draft">${t.type==='command'?'输入命令或 DM8 SQL':'输入本关答案'}</label><textarea id="hub-draft" rows="${t.type==='command'?3:2}" spellcheck="false" autocapitalize="off" ${a.verified?'disabled':''}></textarea>`}<button class="primary" type="submit" ${a.verified?'disabled':''}>执行 / 验证本步</button></form><pre class="hub-terminal" role="status">${esc(hubOutput||'等待输入。本练习不连接真实服务器。')}</pre><div class="gate-result ${a.verified?'passed':''}"><strong>${a.verified?'✓ 验证通过，先读结果':'本步尚未通过'}</strong><button class="primary" data-hub="confirm-task" ${a.verified?'':'disabled'}>确认结果，${a.step===c.tasks.length-1?'完成操作':'进入下一步'}</button></div>`:`<h2>✓ 本关操作完成</h2><p>最后用小测确认理解。答错会留在本关。</p><button class="primary" data-hub="phase" data-id="quiz">进入通关小测</button>`}<details><summary>操作清单</summary><ol>${c.tasks.map((x,i)=>`<li>${i<a.step?'✓ ':''}${esc(x.prompt)}</li>`).join('')}</ol></details></section>`:`<section class="section"><div class="eyebrow">理解才能通关</div><h2>${esc(c.quiz.prompt)}</h2><fieldset><legend>选择后点击检查</legend>${c.quiz.options.map((o,i)=>`<label class="hub-option ${a.answer===i?'is-selected':''}"><input type="radio" name="hub-quiz" value="${i}" ${a.answer===i?'checked':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(o)}</span></label>`).join('')}</fieldset><button class="primary" data-hub="grade-quiz" ${a.answer===null?'disabled':''}>检查答案</button><div class="quiz-feedback" role="status">${esc(a.feedback||'尚未提交答案。')}</div><div class="gate-result ${hubPassed()?'passed':''}"><strong>${hubPassed()?'✓ 本关通过':'完成操作并答对，才能进入下一关'}</strong><button class="primary" data-hub="next" ${hubPassed()?'':'disabled'}>${hubLesson===hubCurriculum[hubTrack].length-1?'查看学习路线':'进入下一关'}</button></div><details><summary>回顾关联知识</summary><p>${esc(c.related)}</p></details></section>`}</main>`;}
function evaluateHubTask(task,value,job){if(task.type==='command'){const result=job.execute(value);const sql=/^(SELECT|EXPLAIN|BACKUP)\b/i.test(task.command);const equal=sql?normalizeDMSQL(value)===normalizeDMSQL(task.command):normalizeJobCommand(value)===normalizeJobCommand(task.command);return {ok:result.ok&&equal&&(!task.expected||result.out.includes(task.expected)),out:result.out+(result.ok&&!equal?'\n命令可执行，但与当前任务不匹配。':'')};}if(task.type==='choice')return {ok:String(value)===String(task.answer),out:String(value)===String(task.answer)?'✓ 正确。'+task.explanation:'还未通过。请回看例子再选择。'};const answer=String(value).trim().toLocaleLowerCase();return {ok:task.answers.some(s=>s.toLocaleLowerCase()===answer),out:task.answers.some(s=>s.toLocaleLowerCase()===answer)?'✓ 正确。'+task.explanation:'还未通过。请核对关键词与示例。'};}
function verifyHubTask(){if(view!=='hub-course'||hubPhase!=='practice'||!hubAttempt.read||hubAttempt.verified)return;const t=activeHubLesson().tasks[hubAttempt.step];if(!t)return;const result=evaluateHubTask(t,hubAttempt.draft,hubEngine);hubAttempt.verified=result.ok;hubOutput=result.out;hubAttempt.output=hubOutput;if(hubTrack==='opswork')hubAttempt.files=hubEngine.fs;hubSave();render();}
function animateResources(){return `<div class="resource-strip"><a href="https://github.com/microsoft/ai-agents-for-beginners" target="_blank" rel="noopener noreferrer">Microsoft Agent 入门</a><a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noopener noreferrer">OpenAI Agents SDK</a><a href="https://github.com/modelcontextprotocol/modelcontextprotocol" target="_blank" rel="noopener noreferrer">MCP 规范</a></div>`;}
function speakJapanese(text){if(!window.speechSynthesis)return toast('设备不支持合成发音，请使用官方音频。');const voices=window.speechSynthesis.getVoices(),voice=voices.find(v=>/^ja/i.test(v.lang));if(!voice)return toast('设备没有可用日语语音；可在系统中安装，或使用官方《彩》音频。');window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';u.voice=voice;u.rate=.85;window.speechSynthesis.speak(u);}
function animeHTML(){return `<main class="hub-main"><div class="page-head"><div><div class="eyebrow">LISTEN IN CONTEXT / 动漫辅助学习</div><h1>看一小段，学一个表达</h1><p>热门作品的官方宣传 / 回顾片段；练习句为原创辅助例句，非视频原字幕。</p></div><a href="https://www.jpfbj.cn/irodori/" target="_blank" rel="noopener noreferrer">系统听力：官方真人音频</a></div><p class="small-note">点击才加载 YouTube 官方视频。播放取决于所在地与网络，加载时会连接第三方平台；无法播放可打开官方链接。宣传片语速较快，先听场景与语气，不把它当作完整分级教材。</p><div class="anime-grid">${animeClips.map((c,i)=>`<article class="section"><span class="chip">${c.level} · ${c.channel}</span><h2>${esc(c.title)}</h2><div id="anime-video-${i}" class="video-box"><button class="primary" data-hub="load-video" data-index="${i}">加载官方片段 ▶</button></div><a href="https://www.youtube.com/watch?v=${c.id}" target="_blank" rel="noopener noreferrer">官方来源</a><p>先听一次，记录角色称呼、情绪与停顿；再看一次，记一个听清的短表达。关注：${c.focus}。</p><div class="worked-example"><b>原创例句 · 不是原片字幕</b><h3>${c.sentence}</h3><p>${c.reading}</p><p>${c.meaning}</p><button class="secondary" data-hub="speak" data-text="${c.sentence}">听设备合成发音</button></div><p>${c.question}</p><div class="filter-tabs">${c.options.map(o=>`<button data-hub="anime-answer" data-index="${i}" data-value="${o}">${o}</button>`).join('')}</div><p id="anime-feedback-${i}" role="status"></p></article>`).join('')}</div></main>`;}
async function loadJP(){const token=jpLevel+':'+jpType;jpStatus='正在读取分级知识库…';jpRows=[];if(view==='jp-library')render();try{const r=await fetch('data/japanese/'+jpType+'-'+jpLevel.toLowerCase()+'.json');if(!r.ok)throw Error('知识库暂时无法加载。');const rows=await r.json();if(token!==jpLevel+':'+jpType)return;jpRows=Array.isArray(rows)?rows:rows.entries||[];jpStatus='';paintJPResults();}catch(e){jpStatus=e.message;paintJPResults();}}
function jpLibraryHTML(){return `<main class="hub-main"><div class="page-head"><div><div class="eyebrow">OPENJLPT / 分级知识库</div><h1>从一个词，读懂一个句子</h1><p>7811 条词汇 · 2383 个汉字 · 526 条文法，支持 N5–N1 检索。</p></div><button class="secondary" data-hub="subject" data-id="japanese">回到引导课程</button></div><div class="reader-tools"><label>等级 <select id="jp-level">${['N5','N4','N3','N2','N1'].map(l=>`<option ${l===jpLevel?'selected':''}>${l}</option>`).join('')}</select></label><label>内容 <select id="jp-type">${[['vocab','词汇'],['kanji','汉字'],['grammar','文法']].map(([id,t])=>`<option value="${id}" ${id===jpType?'selected':''}>${t}</option>`).join('')}</select></label><label class="grow">搜索 <input id="jp-query" value="${esc(jpQuery)}" placeholder="日文、读音或英文释义"></label><button data-hub="jp-search">搜索</button></div><p class="small-note">社区分级并非官方固定出题清单。源库释义为英文，核心课程另有中文讲解。来源 OpenJLPT 0.3.0，保留 JMdict/KANJIDIC2、Tatoeba 等署名；资源数据采用 CC BY-SA 4.0。<a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener noreferrer">源项目</a> · <a href="data/japanese/NOTICE.md" target="_blank">完整署名</a> · <a href="data/japanese/LICENSE" target="_blank">数据许可</a></p><div id="jp-results"></div></main>`;}
function rubyJP(s){const parts=String(s).split(/(\{[^{}|]+\|[^{}]+\})/g);return parts.map(p=>{const m=p.match(/^\{([^|]+)\|([^}]+)\}$/);return m?'<ruby>'+esc(m[1])+'<rt>'+esc(m[2])+'</rt></ruby>':esc(p);}).join('');}
function paintJPResults(){if(view!=='jp-library')return;const node=$('jp-results');if(jpStatus){node.innerHTML='<p role="status">'+esc(jpStatus)+'</p>';return;}const matches=jpRows.filter(r=>JSON.stringify(r).toLowerCase().includes(jpQuery.toLowerCase()));jpPage=Math.min(jpPage,Math.max(0,Math.ceil(matches.length/20)-1));node.innerHTML=`<div class="page-head"><p>${matches.length} 条 · 第 ${jpPage+1}/${Math.max(1,Math.ceil(matches.length/20))} 页</p><div><button data-hub="jp-page" data-delta="-1" ${jpPage===0?'disabled':''}>上一页</button><button data-hub="jp-page" data-delta="1" ${(jpPage+1)*20>=matches.length?'disabled':''}>下一页</button></div></div><div class="jp-grid">${matches.slice(jpPage*20,jpPage*20+20).map(r=>`<article class="section"><span class="chip">${r.level||jpLevel}</span><h2>${esc(r.word||r.character||r.pattern)}</h2><p class="jp-reading">${esc(r.reading||r.romaji||'')}</p><p>${esc((r.meanings||[r.meaning]).filter(Boolean).join('；'))}</p>${r.formation?`<pre>${esc(r.formation)}</pre>`:''}${r.onyomi?`<p>音读：${esc(r.onyomi.join(' / '))}<br>训读：${esc(r.kunyomi.join(' / '))}<br>笔画：${r.strokes}</p>`:''}${r.notes?`<p>${esc(r.notes)}</p>`:''}${(r.examples||[]).slice(0,3).map(e=>`<div class="worked-example"><p lang="ja">${rubyJP(e.furigana||e.ja)}</p><p>${esc(e.en||'')}</p><button class="text-button" data-hub="speak" data-text="${esc(e.ja)}">听合成发音</button></div>`).join('')}<button class="secondary" data-hub="speak" data-text="${esc(r.reading||r.word||r.character||r.pattern)}">听词语发音</button></article>`).join('')}</div>`;}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-hub]');if(!el||el.disabled)return;const d=el.dataset,action=d.hub;pauseDemo();
 try {
 if(action==='home'){view='hub';render();}
 if(action==='subject'){hubSubject=d.id;hubLevel='全部';view='subject';render();}
 if(action==='section'){hubLevel=d.value;render();}
 if(action==='lesson')openHubLesson(d.track,Number(d.index));
 if(action==='read'){hubAttempt.read=true;hubPhase=hubAttempt.phase='practice';hubSave();render();}
 if(action==='phase'){if(d.id==='practice'&&!hubAttempt.read||d.id==='quiz'&&hubAttempt.step!==activeHubLesson().tasks.length)return toast('先按顺序完成本关任务。');hubPhase=hubAttempt.phase=d.id;hubSave();render();}
 if(action==='fill-task'){if(!hubAttempt.verified){hubAttempt.draft=activeHubLesson().tasks[hubAttempt.step].command;hubSave();render();$('hub-draft').focus();}}
 if(action==='confirm-task'){if(!hubAttempt.read||!hubAttempt.verified)return;hubAttempt.step++;hubAttempt.verified=false;hubAttempt.draft='';hubAttempt.output='';hubOutput='';hubAttempt.passed=false;setHubCompletion();render();}
 if(action==='grade-quiz'){if(hubAttempt.step!==activeHubLesson().tasks.length||hubAttempt.answer===null)return;hubAttempt.passed=hubAttempt.answer===activeHubLesson().quiz.answer;hubAttempt.feedback=(hubAttempt.passed?'✓ 答对了，本关通过。':'还没答对，仍在本关。')+activeHubLesson().quiz.explanation;setHubCompletion();render();}
 if(action==='next'){if(!hubPassed())return toast('请先正确完成操作与小测。');if(hubLesson+1<hubCurriculum[hubTrack].length)openHubLesson(hubTrack,hubLesson+1);else{view='subject';render();}}
 if(action==='reset-lesson'){delete hubState.attempts[hubTrack+':'+activeHubLesson().id];hubState.completed[hubTrack]=hubState.completed[hubTrack].filter(id=>id!==activeHubLesson().id);hubSave();openHubLesson(hubTrack,hubLesson);}
 if(action==='books'){view='books';render();refreshLocalBooks();}
 if(action==='book-filter'){bookFilter=d.value;render();}
 if(action==='open-book')await openLibraryBook(d.id);
 if(action==='import'){$('epub-file')?$('epub-file').click():(view='books',render(),$('epub-file').click());}
 if(action==='delete-book'){await localBooks('delete',d.id);await refreshLocalBooks();toast('已移除本设备书籍副本。');}
 if(action==='chapter'){const next=readerIndex+Number(d.delta);if(next>=0&&next<readerBook.chapters.length){readerIndex=next;await showChapter();window.scrollTo({top:0,behavior:'instant'});}}
 if(action==='bookmark'){readerMemory[readerBook.id]={...readerMemory[readerBook.id],bookmark:readerIndex};localStorage.setItem('learning-reader-v1',JSON.stringify(readerMemory));render();toast('书签已保存到当前章节。');}
 if(action==='open-bookmark'){readerIndex=readerMemory[readerBook.id].bookmark;await showChapter();}
 if(action==='save-note'){readerMemory[readerBook.id]={...readerMemory[readerBook.id],note:$('reader-note').value};localStorage.setItem('learning-reader-v1',JSON.stringify(readerMemory));toast('阅读笔记已保存。');}
 if(action==='export-note'){const bytes=new Blob([readerBook.title+'\n'+($('reader-note').value||'')],{type:'text/plain;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(bytes);a.href=url;a.download='reading-note.txt';a.click();URL.revokeObjectURL(url);}
 if(action==='reader-search'){const text=$('reader-search').value.trim();if(!text)return;const content=$('reader-content'),walker=document.createTreeWalker(content,NodeFilter.SHOW_TEXT);let node,found=false;while(node=walker.nextNode()){const at=node.textContent.indexOf(text);if(at>=0){const range=document.createRange();range.setStart(node,at);range.setEnd(node,at+text.length);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);node.parentElement.scrollIntoView({behavior:'smooth',block:'center'});found=true;break;}}if(!found)toast('当前章节没有找到该文本。');}
 if(action==='jp-library'){view='jp-library';jpPage=0;render();await loadJP();}
 if(action==='jp-page'){jpPage=Math.max(0,jpPage+Number(d.delta));paintJPResults();}
 if(action==='jp-search'){jpQuery=$('jp-query').value.trim();jpPage=0;paintJPResults();}
 if(action==='speak')speakJapanese(d.text);
 if(action==='anime'){view='anime';render();}
 if(action==='load-video'){const clip=animeClips[Number(d.index)];$('anime-video-'+d.index).innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${clip.id}" title="${esc(clip.title)}" loading="lazy" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}
 if(action==='anime-answer'){const c=animeClips[Number(d.index)];$('anime-feedback-'+d.index).textContent=d.value===c.answer?'✓ 正确。'+c.meaning:'再试一次，看看原创例句的解释。';}
}catch(error){toast(error.message||'操作失败，请重试。');}
});
document.addEventListener('input',e=>{if(e.target.id==='hub-draft'){hubAttempt.draft=e.target.value;hubAttempt.verified=false;hubSave();}if(e.target.id==='jp-query')jpQuery=e.target.value;});
document.addEventListener('change',async e=>{const target=e.target;if(target.name==='hub-task'){hubAttempt.draft=target.value;hubAttempt.verified=false;hubSave();render();}if(target.name==='hub-quiz'){hubAttempt.answer=Number(target.value);hubAttempt.passed=false;hubAttempt.feedback='';setHubCompletion();render();}if(target.id==='epub-file')await importEpub(target.files[0]);if(target.id==='reader-chapter'){readerIndex=Number(target.value);await showChapter();}if(target.id==='reader-size'){readerSize=Number(target.value);render();}if(target.id==='reader-theme'){readerTheme=target.value;render();}if(target.id==='jp-level'||target.id==='jp-type'){if(target.id==='jp-level')jpLevel=target.value;else jpType=target.value;jpPage=0;await loadJP();}});
view='hub';render();
